<!doctype html><html lang="sw"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard | Konekti Malipo</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Mono&family=Manrope:wght@400;500;600;700;800&display=swap" rel="stylesheet"><style>:root{--ink:#10221d;--muted:#65766e;--cream:#f7f6ef;--card:#fffefa;--line:#dce5dc;--lime:#c6f04b;--teal:#147b67;--deep:#0d4037}*{box-sizing:border-box}body{margin:0;background:var(--cream);font-family:Manrope,Arial;color:var(--ink)}a{text-decoration:none;color:inherit}.shell{max-width:1220px;margin:auto;padding:0 28px}nav{height:76px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}.brand{display:flex;align-items:center;gap:10px;font-size:20px;font-weight:800}.mark{width:31px;height:31px;display:grid;place-items:center;border-radius:10px 10px 3px 10px;background:var(--lime);font-size:22px}.nav-right{display:flex;align-items:center;gap:16px}.help,.logout{font:13px Manrope;font-weight:800;color:var(--muted)}.logout{border:0;background:none;cursor:pointer}.avatar{width:35px;height:35px;display:grid;place-items:center;border-radius:50%;background:var(--deep);color:var(--lime);font-size:13px;font-weight:800}main{padding:46px 0 80px}.overline{font:12px 'DM Mono',monospace;color:var(--teal);letter-spacing:1px;text-transform:uppercase}h1{font-size:clamp(34px,4vw,48px);letter-spacing:-2.3px;line-height:1.08;margin:10px 0}.sub{max-width:650px;color:var(--muted);line-height:1.65}.notice,.error{margin:23px 0;padding:13px 15px;border-radius:10px;font-size:14px}.notice{background:#e4f2d8;color:#28583b}.error{background:#ffe5df;color:#96352d}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:34px 0}.stat{padding:19px 20px;border:1px solid var(--line);border-radius:14px;background:#fffefa}.stat small{display:block;color:var(--muted);font-size:12px;font-weight:700}.stat b{display:block;font-size:25px;letter-spacing:-1px;margin-top:6px}.green{color:var(--teal)}.workspace{display:grid;grid-template-columns:1fr 1fr;gap:17px}.card{padding:26px;border:1px solid var(--line);border-radius:17px;background:var(--card)}.card-head{display:flex;justify-content:space-between;gap:15px;align-items:flex-start}.card h2{font-size:19px;letter-spacing:-.6px;margin:0 0 7px}.hint{margin:0;color:var(--muted);font-size:13px;line-height:1.6}.badge,.pill,.status{padding:5px 8px;border-radius:99px;font:11px 'DM Mono',monospace;white-space:nowrap}.badge,.pill{background:#e4f2d8;color:#286044}.field{margin-top:17px}label{display:block;font-size:12px;font-weight:800;margin-bottom:7px}input,select{width:100%;border:1px solid #cad7cc;border-radius:9px;background:#fff;padding:12px;font:14px Manrope;outline:none}input:focus,select:focus{border-color:var(--teal);box-shadow:0 0 0 4px #147b6713}.two{display:grid;grid-template-columns:1fr 1fr;gap:11px}.button{display:inline-flex;align-items:center;justify-content:center;gap:8px;margin-top:20px;padding:13px 18px;border:0;border-radius:999px;background:var(--ink);color:#fff;font:13px Manrope;font-weight:800;cursor:pointer}.button.lime{background:var(--lime);color:var(--ink)}.wide{grid-column:1/-1}.account{display:flex;align-items:center;gap:13px;padding:15px 0;border-top:1px solid var(--line)}.account:first-of-type{margin-top:15px}.gateway-icon{width:38px;height:38px;display:grid;place-items:center;border-radius:11px;background:#ecf5e2;color:var(--teal);font-weight:800}.account-main{min-width:0;flex:1}.account-main b{font-size:14px}.account-main small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--muted);font-size:12px;margin-top:2px}.empty{padding:34px 0;color:var(--muted);font-size:14px}.payments{width:100%;border-collapse:collapse;margin-top:12px;font-size:14px}.payments th{text-align:left;padding:11px 6px;color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.6px}.payments td{padding:14px 6px;border-top:1px solid var(--line)}.status{background:#f0f2e8;color:#5d6d65}.modal{display:none;position:fixed;z-index:10;inset:0;padding:24px;background:#10221dc9}.modal.open{display:grid;place-items:center}.modal-box{width:min(900px,100%);height:min(780px,100%);position:relative;overflow:hidden;border-radius:18px;background:#fff;box-shadow:0 25px 90px #0008}.close{position:absolute;z-index:3;right:13px;top:13px;border:0;border-radius:99px;padding:8px 12px;background:var(--ink);color:white;font-weight:800;cursor:pointer}.loader{position:absolute;z-index:2;inset:0;display:grid;place-items:center;background:#fff}.loader-content{text-align:center;color:var(--muted);font-size:14px}.spinner{width:44px;height:44px;margin:0 auto 15px;border:4px solid #e5eee4;border-top-color:var(--teal);border-radius:50%;animation:spin .8s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.modal.loaded .loader{display:none}.modal iframe{width:100%;height:100%;border:0;opacity:0}.modal.loaded iframe{opacity:1}@media(max-width:760px){.shell{padding:0 18px}.help,.logout{display:none}.stats,.workspace{grid-template-columns:1fr}.wide{grid-column:auto}.two{grid-template-columns:1fr}.card{padding:21px}}</style></head><body><div class="shell"><nav><a class="brand" href="{{ route('home') }}"><span class="mark">↗</span>Konekti Malipo</a><div class="nav-right"><a class="help" href="{{ route('docs') }}">API docs</a><span class="avatar">{{ strtoupper(substr(auth()->user()->name,0,1)) }}</span><form method="post" action="{{ route('logout') }}">@csrf<button class="logout">Logout</button></form></div></nav><main><span class="overline">Workspace overview</span><h1>Habari, {{ auth()->user()->name }}.</h1><p class="sub">Unganisha gateway yako, kisha test live checkout bila kumpeleka mteja kwenye tab nyingine.</p>@if(session('success'))<div class="notice">✓ {{ session('success') }}</div>@endif @if($errors->any())<div class="error">{{ $errors->first() }}</div>@endif<div class="stats"><div class="stat"><small>Connected gateways</small><b>{{ $accounts->count() }}</b></div><div class="stat"><small>Test payments</small><b>{{ $payments->count() }}</b></div><div class="stat"><small>IPN endpoints ready</small><b class="green">{{ $accounts->whereNotNull('ipn_id')->count() }}</b></div></div><div class="workspace"><section class="card"><div class="card-head"><div><h2>Connect Pesapal</h2><p class="hint">Credentials zako zinahifadhiwa encrypted. IPN ID itasajiliwa automatically.</p></div><span class="badge">ENCRYPTED</span></div><form method="post" action="{{ route('gateway-accounts.pesapal.store') }}">@csrf<div class="two"><div class="field"><label>Environment</label><select name="environment"><option value="production">Production</option><option value="sandbox">Sandbox</option></select></div><div class="field"><label>Consumer key</label><input name="consumer_key" placeholder="Your Pesapal key" required autocomplete="off"></div></div><div class="field"><label>Consumer secret</label><input type="password" name="consumer_secret" placeholder="Your Pesapal secret" required autocomplete="new-password"></div><button class="button">Save & register IPN →</button></form></section><section class="card"><div class="card-head"><div><h2>Test live payment</h2><p class="hint">Checkout itafunguka kwenye modal ndani ya Konekti Malipo.</p></div><span class="badge">HOSTED</span></div>@if($accounts->isEmpty())<div class="empty">Unganisha Pesapal kwanza ili kuanza test.</div>@else<form id="test-form" method="post" action="{{ route('test-payment') }}">@csrf<div class="field"><label>Pesapal account</label><select name="account_id">@foreach($accounts as $account)<option value="{{ $account->id }}">{{ ucfirst($account->environment) }} · IPN {{ $account->ipn_id ? 'ready' : 'pending' }}</option>@endforeach</select></div><div class="two"><div class="field"><label>Amount</label><input type="number" min="1" name="amount" value="1000" required></div><div class="field"><label>Currency</label><select name="currency"><option>TZS</option><option>KES</option><option>UGX</option><option>USD</option></select></div></div><button class="button lime">Open checkout modal →</button></form>@endif</section><section class="card wide"><div class="card-head"><div><h2>Gateway accounts</h2><p class="hint">Accounts zako na status ya IPN endpoint.</p></div></div>@forelse($accounts as $account)<div class="account"><div class="gateway-icon">₽</div><div class="account-main"><b>Pesapal · {{ ucfirst($account->environment) }}</b><small>{{ $account->ipn_url }}</small></div><span class="pill">{{ $account->ipn_id ? 'IPN READY' : 'PENDING' }}</span></div>@empty<div class="empty">Bado hujaunganisha gateway account.</div>@endforelse</section><section class="card wide"><div class="card-head"><div><h2>Recent payments</h2><p class="hint">Malipo ya mwisho yaliyoanzishwa kwenye workspace hii.</p></div></div><table class="payments"><tr><th>Reference</th><th>Amount</th><th>Status</th></tr>@forelse($payments as $payment)<tr><td>{{ $payment->merchant_reference }}</td><td>{{ $payment->currency }} {{ $payment->amount }}</td><td><span class="status">{{ strtoupper($payment->status->value) }}</span></td></tr>@empty<tr><td colspan="3" class="empty">Bado hakuna payment iliyotengenezwa.</td></tr>@endforelse</table></section></div></main></div><div id="checkout-modal" class="modal"><div class="modal-box"><button class="close" type="button" onclick="closeCheckout()">Funga ×</button><div class="loader"><div class="loader-content"><div class="spinner"></div>Inaandaa secure checkout…</div></div><iframe id="checkout-frame" title="Pesapal checkout"></iframe></div></div><script>const form=document.getElementById('test-form'),modal=document.getElementById('checkout-modal'),frame=document.getElementById('checkout-frame');function closeCheckout(){frame.src='';modal.classList.remove('open','loaded')}frame.addEventListener('load',()=>modal.classList.add('loaded'));if(form){form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('button');button.disabled=true;button.textContent='Inaandaa checkout…';try{const r=await fetch(form.action,{method:'POST',body:new FormData(form),headers:{Accept:'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'}}),data=await r.json();if(!r.ok)throw new Error(data.message||'Checkout haikuanzishwa.');modal.classList.remove('loaded');modal.classList.add('open');frame.src=data.checkout_url}catch(error){alert(error.message)}finally{button.disabled=false;button.textContent='Open checkout modal →'}})}</script></body></html>
